WITH filtered AS (SELECT id, device_code, reading_ts, temp_c, pressure, firmware, DATE_FORMAT(reading_ts, 'yyyy-MM') AS reading_ts_label FROM device_readings WHERE humidity < 45), flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM filtered), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT CASE WHEN pressure >= 1024 THEN 'LARGE' ELSE 'SMALL' END AS pressure_tier, DATE_TRUNC('HOUR', reading_ts) AS hour_window, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, ROUND(AVG(is_new_session), 2) AS avg_is_new_session, STDDEV_SAMP(temp_c) AS temp_c_stddev FROM islands GROUP BY CASE WHEN pressure >= 1024 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('HOUR', reading_ts) ORDER BY temp_c_stddev NULLS LAST;
